}
function canonNode(node: Node): string {
  if (node.nodeType === Node.TEXT_NODE) return `#text:${JSON.stringify(node.textContent)}`;
  if (node.nodeType === Node.COMMENT_NODE) return `#comment`;
  const el = node as Element;
