//! Generates `lib/typescript/src/constants.ts` from the canonical Rust protocol
//! constants (`pathland_core::constants`) so the TypeScript DOM renderer's
//! wire-constant mirror cannot drift: every `export const` below is bound to the
//! Rust constant it must match, so a rename breaks this crate's compilation and
//! a revalue changes the emitted file (caught by the CI regen-diff check).
//!
//! The enum *codes* (alignment, shape kind, role, state, …) are protocol-semantic
//! values defined in `spec/MODIFIERS.md`/`spec/OPCODE.md` that today live only in
//! the specs and the renderers; they are enumerated here so the TS side is
//! generated rather than hand-mirrored. They are the renderer-facing copy of the
//! same maps the HTML renderers implement.

use pathland_core::{
    APPEND, border_edges, category, component_type, environment, event, flag, listener, meta,
    property_id, size, style, tree, value_type,
};
use std::fmt::Write;
use std::io;
use std::path::PathBuf;

/// The canonical source of the emitted file (resolved relative to this crate).
pub fn constants_ts_path() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("../../../typescript/src/constants.ts")
}

fn fmt_u8(v: u8) -> String {
    format!("{v:#04x}")
}

fn fmt_u16(v: u16) -> String {
    format!("{v:#06x}")
}

fn fmt_u32(v: u32) -> String {
    format!("{v:#010x}")
}

fn write_consts(out: &mut String, prefix: &str, items: &[(&str, String)]) {
    for (name, value) in items {
        writeln!(out, "export const {prefix}{name} = {value};").unwrap();
    }
}

/// The enum-code tables mirrored from `spec/MODIFIERS.md` / `spec/OPCODE.md`.
/// (These codes are protocol-semantic and have no `pathland_core` consts yet.)
fn enum_codes() -> Vec<(&'static str, Vec<(&'static str, u32)>)> {
    vec![
        ("ALIGN_", vec![("LEADING", 0), ("CENTER", 1), ("TRAILING", 2), ("FILL", 3)]),
        (
            "SHAPE_",
            vec![
                ("CIRCLE", 0),
                ("RECTANGLE", 1),
                ("ROUNDED_RECTANGLE", 2),
                ("CAPSULE", 3),
                ("ELLIPSE", 4),
                ("PATH", 5),
            ],
        ),
        (
            "TEXT_ALIGN_",
            vec![("LEADING", 0), ("CENTER", 1), ("TRAILING", 2)],
        ),
        (
            "TRUNCATION_",
            vec![("HEAD", 0), ("MIDDLE", 1), ("TAIL", 2)],
        ),
        ("CONTENT_MODE_", vec![("FIT", 0), ("FILL", 1)]),
        ("FONT_STYLE_", vec![("NORMAL", 0), ("ITALIC", 1)]),
        (
            "FONT_DESIGN_",
            vec![("DEFAULT", 0), ("SERIF", 1), ("ROUNDED", 2), ("MONOSPACED", 3)],
        ),
        ("TEXT_CASE_", vec![("NONE", 0), ("UPPERCASE", 1), ("LOWERCASE", 2)]),
        (
            "CONTROL_SIZE_",
            vec![("SMALL", 0), ("REGULAR", 1), ("LARGE", 2)],
        ),
        (
            "DATE_PICKER_MODE_",
            vec![("DATE", 0), ("TIME", 1), ("DATE_AND_TIME", 2)],
        ),
        (
            "PICKER_STYLE_",
            vec![("MENU", 0), ("SEGMENTED", 1), ("WHEEL", 2), ("RADIO_GROUP", 3)],
        ),
        (
            "TOGGLE_STYLE_",
            vec![("SWITCH", 0), ("CHECKBOX", 1), ("BUTTON", 2)],
        ),
        (
            "ROLE_",
            vec![
                ("NONE", 0),
                ("BUTTON", 1),
                ("LINK", 2),
                ("HEADER", 3),
                ("TEXT", 4),
                ("IMAGE", 5),
                ("TEXT_FIELD", 6),
                ("SLIDER", 7),
                ("TOGGLE", 8),
                ("CHECKBOX", 9),
                ("RADIO_BUTTON", 10),
                ("STEPPER", 11),
                ("TAB", 12),
                ("TAB_BAR", 13),
                ("LIST", 14),
                ("GRID", 15),
                ("SCROLL_VIEW", 16),
                ("ADJUSTABLE", 17),
                ("SUMMARY", 18),
                ("MENU", 19),
            ],
        ),
        (
            "STATE_",
            vec![
                ("NORMAL", 0),
                ("DISABLED", 1),
                ("FOCUSED", 2),
                ("PRESSED", 3),
                ("SELECTED", 4),
                ("EXPANDED", 5),
                ("BUSY", 6),
            ],
        ),
    ]
}

/// Emit the full `constants.ts`.
pub fn emit_constants_ts() -> String {
    let mut out = String::new();
    let mut block = |prefix: &str, items: &[(&str, String)]| {
        write_consts(&mut out, prefix, items);
    };

    out.push_str(
        "// Generated by `cargo run -p pathland-ts-codegen` (lib/rust). Do not edit.\n\
         // Wire constants are bound to `pathland_core::constants`; enum codes mirror\n\
         // spec/MODIFIERS.md + spec/OPCODE.md. Regenerate with `npm run regen`.\n\n\
         // Batch header\n",
    );
    block("", &[
        ("MAGIC", format!("{:#x}", 0x504c504cu32)),
        ("VERSION", "1".into()),
        ("HEADER_SIZE", "16".into()),
        ("OPCODE_SIZE", "16".into()),
        ("FLAG_HOST_TO_GUEST", "0x0001".into()),
    ]);
    out.push_str("\n// Categories\n");
    block("CAT_", &[
        ("TREE", fmt_u8(category::TREE)),
        ("STYLE", fmt_u8(category::STYLE)),
        ("EVENT", fmt_u8(category::EVENT)),
        ("META", fmt_u8(category::META)),
    ]);
    out.push_str("\n// TREE commands\n");
    block("CMD_", &[
        ("CREATE_NODE", fmt_u8(tree::CREATE_NODE)),
        ("DELETE_NODE", fmt_u8(tree::DELETE_NODE)),
        ("INSERT_CHILD", fmt_u8(tree::INSERT_CHILD)),
        ("REMOVE_CHILD", fmt_u8(tree::REMOVE_CHILD)),
        ("MOVE_CHILD", fmt_u8(tree::MOVE_CHILD)),
    ]);
    out.push_str("\n// STYLE commands\n");
    block("CMD_", &[
        ("SET_PROPERTY", fmt_u8(style::SET_PROPERTY)),
        ("SET_DESIGN_TOKEN", fmt_u8(style::SET_DESIGN_TOKEN)),
        ("SET_TEXT", fmt_u8(style::SET_TEXT)),
        ("SET_DATE", fmt_u8(style::SET_DATE)),
    ]);
    out.push_str("\n// META commands\n");
    block("CMD_", &[
        ("RESET", fmt_u8(meta::RESET)),
        ("ENVIRONMENT", fmt_u8(meta::ENVIRONMENT)),
        ("RESYNC", fmt_u8(meta::RESYNC)),
    ]);
    out.push_str("\n// META::ENVIRONMENT field ids (spec/OPCODE.md §Environment fields)\n");
    block("ENV_", &[
        ("VIEWPORT_WIDTH", fmt_u16(environment::VIEWPORT_WIDTH)),
        ("VIEWPORT_HEIGHT", fmt_u16(environment::VIEWPORT_HEIGHT)),
        ("ROUTE", fmt_u16(environment::ROUTE)),
    ]);
    out.push_str("\n// EVENT commands (host -> guest)\n");
    block("CMD_", &[
        ("POINTER_DOWN", fmt_u8(event::POINTER_DOWN)),
        ("POINTER_MOVE", fmt_u8(event::POINTER_MOVE)),
        ("POINTER_UP", fmt_u8(event::POINTER_UP)),
        ("KEY_DOWN", fmt_u8(event::KEY_DOWN)),
        ("KEY_UP", fmt_u8(event::KEY_UP)),
        ("VALUE_CHANGED", fmt_u8(event::VALUE_CHANGED)),
        ("TEXT_CHANGED", fmt_u8(event::TEXT_CHANGED)),
        ("FOCUS_CHANGED", fmt_u8(event::FOCUS_CHANGED)),
        ("EDITING_CHANGED", fmt_u8(event::EDITING_CHANGED)),
        ("SUBMIT", fmt_u8(event::SUBMIT)),
        ("SCROLL", fmt_u8(event::SCROLL)),
        ("WHEEL", fmt_u8(event::WHEEL)),
        ("DATE_CHANGED", fmt_u8(event::DATE_CHANGED)),
        ("NAVIGATE", fmt_u8(event::NAVIGATE)),
    ]);
    out.push_str("\n// EVENT flags\n");
    block("FLAG_", &[
        ("POINTER_SECONDARY", fmt_u16(flag::POINTER_SECONDARY)),
        ("HOVER_ENTER", fmt_u16(flag::HOVER_ENTER)),
        ("HOVER_LEAVE", fmt_u16(flag::HOVER_LEAVE)),
        ("KEY_REPEAT", fmt_u16(flag::KEY_REPEAT)),
        ("NAVIGATE_URL", fmt_u16(flag::NAVIGATE_URL)),
    ]);
    out.push_str("\n// EVENT_LISTENERS bits (spec/EVENTS.md)\n");
    block("LISTEN_", &[
        ("POINTER_DOWN", fmt_u32(listener::POINTER_DOWN)),
        ("POINTER_MOVE", fmt_u32(listener::POINTER_MOVE)),
        ("POINTER_UP", fmt_u32(listener::POINTER_UP)),
        ("KEY_DOWN", fmt_u32(listener::KEY_DOWN)),
        ("KEY_UP", fmt_u32(listener::KEY_UP)),
        ("FOCUS", fmt_u32(listener::FOCUS)),
        ("EDITING", fmt_u32(listener::EDITING)),
        ("SUBMIT", fmt_u32(listener::SUBMIT)),
        ("SCROLL", fmt_u32(listener::SCROLL)),
        ("WHEEL", fmt_u32(listener::WHEEL)),
    ]);
    out.push_str("\n// Value types (spec/OPCODE.md)\n");
    block("VAL_", &[
        ("U8", fmt_u8(value_type::U8)),
        ("U32", fmt_u8(value_type::U32)),
        ("I32", fmt_u8(value_type::I32)),
        ("F32", fmt_u8(value_type::F32)),
        ("STRING", fmt_u8(value_type::STRING)),
        ("ENUM", fmt_u8(value_type::ENUM)),
        ("COLOR", fmt_u8(value_type::COLOR)),
        ("DESIGN_TOKEN", fmt_u8(value_type::DESIGN_TOKEN)),
    ]);
    out.push_str("\n// Property IDs (spec/MODIFIERS.md)\n");
    block(
        "PROP_",
        &[
            ("SPACING", fmt_u16(property_id::SPACING)),
            ("ALIGNMENT", fmt_u16(property_id::ALIGNMENT)),
            ("CONTENT_MARGINS", fmt_u16(property_id::CONTENT_MARGINS)),
            ("SHAPE_KIND", fmt_u16(property_id::SHAPE_KIND)),
            ("TEXT", fmt_u16(property_id::TEXT)),
            ("LINE_LIMIT", fmt_u16(property_id::LINE_LIMIT)),
            ("TEXT_ALIGNMENT", fmt_u16(property_id::TEXT_ALIGNMENT)),
            ("TRUNCATION_MODE", fmt_u16(property_id::TRUNCATION_MODE)),
            ("OFFSET_X", fmt_u16(property_id::OFFSET_X)),
            ("OFFSET_Y", fmt_u16(property_id::OFFSET_Y)),
            ("POSITION_X", fmt_u16(property_id::POSITION_X)),
            ("POSITION_Y", fmt_u16(property_id::POSITION_Y)),
            ("MIN_WIDTH", fmt_u16(property_id::MIN_WIDTH)),
            ("IDEAL_WIDTH", fmt_u16(property_id::IDEAL_WIDTH)),
            ("MAX_WIDTH", fmt_u16(property_id::MAX_WIDTH)),
            ("MIN_HEIGHT", fmt_u16(property_id::MIN_HEIGHT)),
            ("IDEAL_HEIGHT", fmt_u16(property_id::IDEAL_HEIGHT)),
            ("MAX_HEIGHT", fmt_u16(property_id::MAX_HEIGHT)),
            ("FIXED_SIZE_HORIZONTAL", fmt_u16(property_id::FIXED_SIZE_HORIZONTAL)),
            ("FIXED_SIZE_VERTICAL", fmt_u16(property_id::FIXED_SIZE_VERTICAL)),
            ("LAYOUT_PRIORITY", fmt_u16(property_id::LAYOUT_PRIORITY)),
            ("ASPECT_RATIO", fmt_u16(property_id::ASPECT_RATIO)),
            ("CONTENT_MODE", fmt_u16(property_id::CONTENT_MODE)),
