//! Canonical design-token conventions shared with the TypeScript DOM client
//! (generated into `lib/typescript/src/tokens.ts` by `pathland-ts-codegen`).

/// The scheme prefix stripped when naming the CSS variable.
pub const DARK_PREFIX: &str = "dark.";

/// CSS variable prefix.
pub const VAR_PREFIX: &str = "--pl-";

/// The generative space family resolves to `calc(var(--pl-space-base) * N)`.
pub const SPACE_FAMILY: &str = "space.";

/// Token paths whose F32 values are CSS lengths (get `px` appended).
pub const LENGTH_PREFIXES: &[&str] = &[
    "space.",
    "radius.",
    "border.width.",
    "size.control.",
    "control.padding.",
    "control.height.",
];

/// Prefix/suffix rules for length tokens.
pub const LENGTH_PREFIX_SUFFIX: &[(&str, &str)] = &[
    ("control.font.", ".size"),
    ("font.heading.", ".size"),
];

/// Exact length-token paths.
pub const LENGTH_EXACT: &[&str] = &["font.body.size", "font.caption.size"];

/// Elevation component suffixes that are lengths.
pub const LENGTH_ELEVATION_SUFFIXES: &[&str] = &[".radius", ".x", ".y", ".blur"];

/// Characters preserved verbatim in a CSS variable name.
pub const VAR_NAME_PRESERVED: &str = "A-Za-z0-9_-";
```

